use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let text = input["text"].as_str().unwrap_or_default();
    let shift = input["shift"].as_i64().unwrap_or_default();
    let mut result = String::new();
    for c in text.chars() {
        if c.is_ascii_lowercase() {
            let offset = c as u8 - 'a' as u8;
            let new_offset = (offset + shift) % 26 + 'a' as u8;
            result.push(new_offset as char);
        } else {
            result.push(c);
        }
    }
    result
}

fn main() {
    let input = serde_json::Value::from("{\"text\":\"xyz A!\",\"shift\":3}");
    let expected = serde_json::Value::from("abc A!");
    assert_eq!(solve(input), expected);
}
